CREATE TABLE wu_guard_rows(id TEXT PRIMARY KEY,phase TEXT NOT NULL);
CREATE TABLE wu_view_terms(id TEXT PRIMARY KEY,organization_id UUID NOT NULL,series_id UUID NOT NULL,amount NUMERIC NOT NULL);
CREATE PROCEDURE wg_commit() LANGUAGE plpgsql AS $$BEGIN COMMIT;END$$;
CREATE PROCEDURE wg_rollback() LANGUAGE plpgsql AS $$BEGIN ROLLBACK;END$$;
CREATE PROCEDURE wg_commit_chain() LANGUAGE plpgsql AS $$BEGIN COMMIT AND CHAIN;END$$;
CREATE PROCEDURE wg_rollback_chain() LANGUAGE plpgsql AS $$BEGIN ROLLBACK AND CHAIN;END$$;
CREATE PROCEDURE wg_dynamic_commit() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'COM' || 'MIT';END$$;
CREATE PROCEDURE wg_dynamic_rollback() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'ROLLBACK';END$$;
CREATE PROCEDURE wg_dynamic_begin() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'BEGIN';END$$;
CREATE PROCEDURE wg_prepare() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'PREPARE TRANSACTION ''wg_private''';END$$;
CREATE PROCEDURE wg_commit_prepared() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'COMMIT PREPARED ''wg_private''';END$$;
CREATE PROCEDURE wg_rollback_prepared() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'ROLLBACK PREPARED ''wg_private''';END$$;
CREATE PROCEDURE wg_caught_commit() LANGUAGE plpgsql AS $$BEGIN COMMIT;EXCEPTION WHEN OTHERS THEN NULL;END$$;
CREATE PROCEDURE wg_caught_dynamic() LANGUAGE plpgsql AS $$BEGIN EXECUTE 'COMMIT';EXCEPTION WHEN OTHERS THEN NULL;END$$;
CREATE PROCEDURE wg_rethrow() LANGUAGE plpgsql AS $$BEGIN COMMIT;EXCEPTION WHEN OTHERS THEN RAISE;END$$;
CREATE PROCEDURE wg_notice() LANGUAGE plpgsql AS $$BEGIN RAISE NOTICE 'Private caller boundary control';COMMIT;END$$;
CREATE PROCEDURE wg_savepoint() LANGUAGE plpgsql AS $$BEGIN SAVEPOINT wg_local;ROLLBACK TO SAVEPOINT wg_local;RELEASE SAVEPOINT wg_local;END$$;
CREATE PROCEDURE wg_spoof() LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'transaction control is not permitted inside a host-owned application transaction' USING ERRCODE='2D000';END$$;
CREATE VIEW wu_view_invoker WITH (security_invoker = true) AS SELECT series_id,bicdb_exact_sum_units(amount,2) AS value FROM wu_view_terms WHERE organization_id=CAST(current_setting('bicdb.current_tenant',true) AS UUID) GROUP BY series_id;
CREATE VIEW wu_view_definer AS SELECT series_id,bicdb_exact_sum_units(amount,2) AS value FROM wu_view_terms WHERE organization_id=CAST(current_setting('bicdb.current_tenant',true) AS UUID) GROUP BY series_id;
